"""
wiki_evaluate.py: 独立 Evaluator — 评估 wiki-build 生成的页面质量。

原则：Evaluator 必须独立于 Generator，天然倾向怀疑而非夸奖。
评估维度：
  1. 结构完整性（frontmatter 字段是否齐全）
  2. 中文质量（翻译内容是否真的是中文）
  3. 引用准确性（sources 指向的文件是否存在）
  4. 知识连接（wikilink 数量是否足够）
  5. 语义质量（用 Gemini 作为独立裁判评分）
"""

import argparse
import json
import os
import re
import subprocess
import sys
import urllib.request
from datetime import datetime, timezone
from pathlib import Path


def log(msg):
    print(f"[wiki-evaluate] {msg}", flush=True)


def send_tg(text: str):
    token = os.environ.get("YOUTUBE_WIKI_TG_TOKEN", "")
    chat_id = os.environ.get("YOUTUBE_WIKI_TG_CHAT_ID", "")
    if not token or not chat_id:
        return
    try:
        subprocess.run([
            "curl", "-s", "-X", "POST",
            f"https://api.telegram.org/bot{token}/sendMessage",
            "-d", f"chat_id={chat_id}",
            "-d", "disable_web_page_preview=true",
            "--data-urlencode", f"text={text}",
            "--max-time", "10",
        ], capture_output=True)
    except Exception:
        pass


def call_gemini(prompt: str) -> str:
    api_key = os.environ.get("GOOGLE_CLOUD_API_KEY", "")
    if not api_key:
        raise RuntimeError("GOOGLE_CLOUD_API_KEY not set")
    model = os.environ.get("WIKI_GEMINI_MODEL", "gemini-2.0-flash-lite")
    payload = json.dumps({
        "contents": [{"role": "user", "parts": [{"text": prompt}]}],
        "generationConfig": {"temperature": 0.1, "maxOutputTokens": 2000},
    }).encode()
    url = (f"https://aiplatform.googleapis.com/v1/publishers/google/models"
           f"/{model}:generateContent?key={api_key}")
    req = urllib.request.Request(
        url, data=payload, headers={"Content-Type": "application/json"}
    )
    with urllib.request.urlopen(req, timeout=60) as resp:
        data = json.loads(resp.read())
    return data["candidates"][0]["content"]["parts"][0]["text"]


def parse_frontmatter(text: str) -> tuple[dict, str]:
    if not text.startswith("---"):
        return {}, text
    parts = text.split("---", 2)
    if len(parts) < 3:
        return {}, text
    try:
        import yaml
        meta = yaml.safe_load(parts[1]) or {}
        return meta, parts[2].lstrip("\n")
    except Exception:
        return {}, text


def check_structure(page: Path, wiki_path: Path) -> list[str]:
    """检查 frontmatter 结构完整性"""
    issues = []
    text = page.read_text(encoding="utf-8")
    meta, body = parse_frontmatter(text)

    required = ["title", "type", "tags", "summary", "sources"]
    for field in required:
        if field not in meta or not meta[field]:
            issues.append(f"缺少字段: {field}")

    # 检查 sources 文件实际存在
    for src in meta.get("sources", []):
        src_path = wiki_path / src.lstrip("/")
        if not src_path.exists():
            issues.append(f"引用文件不存在: {src}")

    # 检查 wikilink 数量
    wikilinks = re.findall(r'\[\[.+?\]\]', body)
    if len(wikilinks) < 2:
        issues.append(f"wikilink 不足 2 个（当前 {len(wikilinks)} 个）")

    return issues


def check_chinese_quality(page: Path) -> float:
    """检查中文字符比例"""
    text = page.read_text(encoding="utf-8")
    _, body = parse_frontmatter(text)
    chinese = len(re.findall(r'[一-鿿]', body))
    total = len(body.replace(" ", "").replace("\n", ""))
    return chinese / max(total, 1)


def semantic_evaluate(pages_sample: list[Path]) -> dict:
    """用 Gemini 作为独立裁判评估语义质量"""
    if not pages_sample:
        return {"score": 1.0, "feedback": "无页面"}

    sample_content = ""
    for p in pages_sample[:3]:  # 最多取3页
        text = p.read_text(encoding="utf-8")[:1500]
        sample_content += f"\n\n=== {p.name} ===\n{text}"

    prompt = f"""你是一个严格的 wiki 质量评审员，天然倾向怀疑而非夸奖。

请评估以下 wiki 页面的质量（0.0 到 1.0 分）：

评分标准：
- 内容是否准确反映原文核心概念
- 中文是否流畅自然（非机翻痕迹）
- 知识点之间的连接是否有意义
- 是否存在错误或明显遗漏

只返回 JSON：{{"score": 0.0-1.0, "feedback": "一句话评语", "issues": ["具体问题1", "具体问题2"]}}

待评页面：
{sample_content}
"""
    try:
        result = call_gemini(prompt)
        # 提取 JSON
        json_match = re.search(r'\{[^{}]+\}', result, re.DOTALL)
        if json_match:
            return json.loads(json_match.group(0))
    except Exception as e:
        log(f"语义评估失败: {e}")
    return {"score": 0.8, "feedback": "评估跳过", "issues": []}


def _push_status_commit(wiki_path: Path, run_id: str, evaluation: dict):
    """更新 pipeline-context.json 并推 stage-evaluate done commit，确保 tg-notify 触发"""
    ctx_file = wiki_path / "raw" / "pipeline-context.json"
    try:
        ctx = json.loads(ctx_file.read_text()) if ctx_file.exists() else {}
    except Exception:
        ctx = {}
    if "stage_c" not in ctx:
        ctx["stage_c"] = {}
    ctx["stage_c"]["evaluation"] = evaluation
    ctx_file.parent.mkdir(parents=True, exist_ok=True)
    ctx_file.write_text(json.dumps(ctx, ensure_ascii=False, indent=2))
    try:
        subprocess.run(["git", "add", str(ctx_file)],
                       cwd=wiki_path, check=True, capture_output=True)
        subprocess.run([
            "git", "commit", "-m",
            f"chore: stage-evaluate done [{run_id}] [score:{evaluation.get('score',1.0):.2f}]"
        ], cwd=wiki_path, check=True, capture_output=True)
        subprocess.run(["git", "push", "origin", "main"],
                       cwd=wiki_path, check=True, capture_output=True)
        log("git push ✅ (status commit)")
    except subprocess.CalledProcessError as e:
        log(f"status commit 失败: {e}")


def get_new_pages(wiki_path: Path, run_id: str) -> list[Path]:
    """获取本次 wiki-build 新生成的页面"""
    result = subprocess.run(
        ["git", "-c", "core.quotepath=false", "diff",
         "--name-only", "HEAD~1", "HEAD", "--", "wiki/"],
        cwd=wiki_path, capture_output=True, text=True
    )
    files = []
    for line in result.stdout.strip().split("\n"):
        line = line.strip().strip('"')
        if not line or not line.endswith(".md") or line.endswith(".gitkeep"):
            continue
        p = wiki_path / line
        if p.exists():
            files.append(p)
    return files


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--wiki-path", required=True)
    parser.add_argument("--run-id", required=True)
    parser.add_argument("--git-push", action="store_true")
    args = parser.parse_args()

    wiki_path = Path(args.wiki_path).expanduser()

    # git sync
    subprocess.run(["git", "fetch", "origin", "main"],
                   cwd=wiki_path, capture_output=True)
    subprocess.run(["git", "reset", "--hard", "origin/main"],
                   cwd=wiki_path, capture_output=True)

    new_pages = get_new_pages(wiki_path, args.run_id)
    if not new_pages:
        log("无新页面可评估，推送状态 commit 以触发 tg-notify")
        if args.git_push:
            _push_status_commit(wiki_path, args.run_id, {
                "pages_evaluated": 0,
                "status": "skipped",
                "score": 1.0,
                "feedback": "无新页面，跳过评估"
            })
        sys.exit(0)

    log(f"评估 {len(new_pages)} 个新页面")
    send_tg(f"🔍 [WIKI-EVALUATE] 开始评估\n   {len(new_pages)} 个新页面")

    # ── 1. 结构检查 ──
    struct_issues = {}
    for page in new_pages:
        issues = check_structure(page, wiki_path)
        if issues:
            struct_issues[page.name] = issues

    # ── 2. 中文质量检查 ──
    low_chinese = []
    for page in new_pages:
        ratio = check_chinese_quality(page)
        if ratio < 0.15:
            low_chinese.append(f"{page.name} ({ratio:.0%})")

    # ── 3. 语义评估（Gemini 作为独立裁判）──
    source_pages = [p for p in new_pages if "sources" in str(p)]
    semantic = semantic_evaluate(source_pages or new_pages)

    # ── 汇总 ──
    passed = not struct_issues and not low_chinese and semantic["score"] >= 0.6

    evaluation = {
        "run_id": args.run_id,
        "timestamp": datetime.now(timezone.utc).isoformat(),
        "pages_evaluated": len(new_pages),
        "status": "passed" if passed else "needs_review",
        "score": semantic["score"],
        "feedback": semantic.get("feedback", ""),
        "struct_issues": struct_issues,
        "low_chinese_pages": low_chinese,
        "semantic_issues": semantic.get("issues", []),
    }

    log(f"评估结果: status={evaluation['status']} score={evaluation['score']:.2f}")

    # ── 写入 pipeline-context.json ──
    ctx_file = wiki_path / "raw" / "pipeline-context.json"
    if ctx_file.exists():
        try:
            ctx = json.loads(ctx_file.read_text())
        except Exception:
            ctx = {}
    else:
        ctx = {}

    if "stage_c" not in ctx:
        ctx["stage_c"] = {}
    ctx["stage_c"]["evaluation"] = evaluation
    ctx["stage_c"]["handoff"] = {
        "evaluated_at": evaluation["timestamp"],
        "quality_gate": "passed" if passed else "needs_review",
        "for_tg_notify": {
            "eval_score": evaluation["score"],
            "eval_status": evaluation["status"],
            "eval_feedback": evaluation["feedback"],
        }
    }
    ctx_file.write_text(json.dumps(ctx, ensure_ascii=False, indent=2))

    # ── TG 通知 ──
    if passed:
        send_tg(
            f"✅ [WIKI-EVALUATE] 质量评估通过\n"
            f"   评分: {evaluation['score']:.0%}\n"
            f"   {evaluation['feedback']}\n"
            f"   {len(new_pages)} 个页面"
        )
    else:
        issues_text = ""
        if struct_issues:
            issues_text += f"\n结构问题: {len(struct_issues)} 个文件"
        if low_chinese:
            issues_text += f"\n中文不足: {', '.join(low_chinese[:3])}"
        if semantic.get("issues"):
            issues_text += f"\n语义问题: {'; '.join(semantic['issues'][:2])}"
        send_tg(
            f"⚠️ [WIKI-EVALUATE] 质量需要关注\n"
            f"   评分: {evaluation['score']:.0%}\n"
            f"   {evaluation['feedback']}{issues_text}"
        )

    if args.git_push:
        try:
            subprocess.run(["git", "add", str(ctx_file)],
                           cwd=wiki_path, check=True, capture_output=True)
            subprocess.run([
                "git", "commit", "-m",
                f"chore: stage-evaluate done [{args.run_id}] "
                f"[score:{evaluation['score']:.2f}]"
            ], cwd=wiki_path, check=True, capture_output=True)
            subprocess.run(["git", "push", "origin", "main"],
                           cwd=wiki_path, check=True, capture_output=True)
            log("git push ✅")
        except subprocess.CalledProcessError as e:
            log(f"git push 失败: {e}")

    sys.exit(0 if passed else 1)


if __name__ == "__main__":
    main()
